import { forwardRef, type AnchorHTMLAttributes } from 'react';

type LinkButtonSize = 'xs' | 'sm' | 'default' | 'lg' | 'xl';

export type LinkButtonProps = {
  size?: LinkButtonSize;
  disabled?: boolean;
  animated?: boolean;
  children: string;
  className?: string;
  href: string;
} & Omit<AnchorHTMLAttributes<HTMLAnchorElement>, 'children'>;

function cn(...classes: (string | false | undefined | null)[]) {
  return classes.filter(Boolean).join(' ');
}

export const LinkButton = forwardRef<HTMLAnchorElement, LinkButtonProps>(
  (
    {
      size = 'default',
      disabled = false,
      animated = false,
      children,
      className,
      href,
      ...props
    },
    ref,
  ) => {
    const classes = cn(
      'link-button',
      `link-button--${size}`,
      disabled && 'link-button--disabled',
      animated && 'link-button--animated',
      className,
    );

    return (
      <a
        ref={ref}
        className={classes}
        href={href}
        aria-disabled={disabled || undefined}
        target="_blank"
        rel="noopener noreferrer"
        {...props}
      >
        <span className="link-button__text">{children}</span>
      </a>
    );
  },
);

LinkButton.displayName = 'LinkButton';

/* -------------------------------------------------------------------------
   Link Button

   Semantic link (<a>) for external navigation. Not a button.
   Blue text with animated underline on hover. No background, no border.

   Sizes:    xs, sm, default, lg, xl
   States:   enabled, hover, focus, disabled
   ------------------------------------------------------------------------- */

.link-button {
  display: inline-flex;
  align-items: center;
  gap: 0.5em;
  padding: 0;
  background: none;
  border: none;
  font-family: var(--font-family-sans), ui-sans-serif, system-ui, sans-serif;
  font-weight: var(--font-weight-medium);
  line-height: 1;
  color: var(--link-button-fg-enabled);
  cursor: pointer;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  text-decoration: none;
  transition: color 0.3s cubic-bezier(0.19, 1, 0.22, 1);
}

.link-button:hover:not(.link-button--disabled) {
  color: var(--link-button-fg-hover);
}

.link-button:active:not(.link-button--disabled) {
  color: var(--link-button-fg-pressed);
}

.link-button:focus-visible {
  outline: var(--ring-width) solid var(--ring);
  outline-offset: var(--ring-offset);
  border-radius: 0.125em;
}

@media (prefers-reduced-motion: reduce) {
  .link-button {
    transition-duration: 0ms;
  }
}

/* ---- Sizes ---- */

.link-button--xs      { font-size: var(--font-size-xs); }
.link-button--sm      { font-size: var(--font-size-sm); }
.link-button--default { font-size: var(--font-size-base); }
.link-button--lg      { font-size: var(--font-size-lg); }
.link-button--xl      { font-size: var(--font-size-xl); }

/* ---- States ---- */

.link-button--disabled {
  color: var(--link-button-fg-disabled);
  cursor: not-allowed;
  pointer-events: none;
}

/* ---- Parts ---- */

.link-button__text {
  display: inline;
  position: relative;
}

/* ---- Underline animation ---- */

.link-button__text::before {
  content: "";
  position: absolute;
  bottom: -0.0625em;
  left: 0;
  width: 100%;
  height: 0.0625em;
  background-color: currentColor;
  transition: transform 0.735s cubic-bezier(0.625, 0.05, 0, 1);
  transform-origin: right;
  transform: scaleX(0) rotate(0.001deg);
}

@media (hover: hover) and (pointer: fine) {
  .link-button--animated:hover:not(.link-button--disabled) .link-button__text::before,
  [data-hover]:hover .link-button--animated:not(.link-button--disabled) .link-button__text::before {
    transform-origin: left;
    transform: scaleX(1) rotate(0.001deg);
  }
}

/* ---- Animated variant: persistent underline + text shimmer ---- */

.link-button--animated:not(.link-button--disabled) .link-button__text::before {
  transform-origin: left;
  transform: scaleX(1) rotate(0.001deg);
}

.link-button--animated:not(.link-button--disabled) .link-button__text {
  background: linear-gradient(
    120deg,
    currentColor 0%,
    currentColor 35%,
    color-mix(in srgb, currentColor 40%, white) 50%,
    currentColor 65%,
    currentColor 100%
  );
  background-size: 200% 100%;
  background-clip: text;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: link-button-shimmer 3s ease-in-out infinite;
}

@keyframes link-button-shimmer {
  0%, 100% { background-position: 200% center; }
  50% { background-position: 0% center; }
}

@media (prefers-reduced-motion: reduce) {
  .link-button--animated:not(.link-button--disabled) .link-button__text {
    animation: none;
    background: none;
    -webkit-text-fill-color: currentColor;
  }
}
